  "text": "Rassistische Diskriminierungen und Angriffe auf Menschen wegen Herkunft, Hautfarbe, Religion, Weltanschauung, Erscheinungsbild, sexueller Orientierung oder Geschlechtsidentität werden **konsequent verfolgt**. Betroffene und ihre **Proteste werden unterstützt**."
